// AI generated by: Claude Code / claude-opus-5-5
// Prompt: "Parts and content analysis (prefactor)"
// Changes: Part helpers – read, write and compare each of the four parts (definition, grammar rules, precedence
//          table, reduction rules) of project content. Export naming and simulation inputs are not parts: writing
//          a part never touches them, and comparing parts ignores them. Pure, no DOM (shared by UI and server).

import { precTable, setTerminals } from './precedence'
import type { ProjectData, Relation } from './project'

export const PARTS = ['definition', 'grammarRules', 'precTable', 'reductionRules'] as const
export type PartName = (typeof PARTS)[number]

/** The value of each part. */
export interface Parts {
  /** Declared N and T (one symbol per line with an optional note) and the chosen start symbol S. */
  definition: { nonterminals: string; terminals: string; start: string }
  /** Rules P, one per line. */
  grammarRules: string
  /** Precedence terminals (without $) and the relations, keyed like ProjectData['prec']['cells']. */
  precTable: { terminals: string[]; cells: Record<string, Relation> }
  /** Rules the precedence simulation reduces by. */
  reductionRules: string
}

/** The value of one part of the content (a copy – changing it does not change the content). */
export function readPart<P extends PartName>(data: ProjectData, part: P): Parts[P] {
  const read: { [K in PartName]: () => Parts[K] } = {
    definition: () => ({ ...data.def }),
    grammarRules: () => data.ll.grammar,
    precTable: () => ({ terminals: [...data.prec.terminals], cells: { ...data.prec.cells } }),
    reductionRules: () => data.prec.rules,
  }
  return read[part]()
}

/** The content with one part replaced; the other parts, export naming and simulation inputs stay as they are. */
export function writePart<P extends PartName>(data: ProjectData, part: P, value: Parts[P]): ProjectData {
  const write: { [K in PartName]: (v: Parts[K]) => ProjectData } = {
    definition: (v) => ({ ...data, def: { nonterminals: v.nonterminals, terminals: v.terminals, start: v.start.trim() } }),
    grammarRules: (v) => ({ ...data, ll: { ...data.ll, grammar: v } }),
    // setTerminals normalizes the terminals (unique, no $) and drops relations of terminals the table does not have.
    precTable: (v) => ({ ...data, prec: setTerminals({ ...data.prec, cells: { ...v.cells } }, v.terminals) }),
    reductionRules: (v) => ({ ...data, prec: { ...data.prec, rules: v } }),
  }
  return write[part](value)
}

/** All four parts of the content. */
export const readParts = (data: ProjectData): Parts => ({
  definition: readPart(data, 'definition'),
  grammarRules: readPart(data, 'grammarRules'),
  precTable: readPart(data, 'precTable'),
  reductionRules: readPart(data, 'reductionRules'),
})

/** The content with the given parts replaced (e.g. a draft's parts over its project's export naming and inputs). */
export function writeParts(data: ProjectData, parts: Partial<Parts>): ProjectData {
  return PARTS.reduce((d, part) => (parts[part] === undefined ? d : writePart(d, part, parts[part] as Parts[typeof part])), data)
}

const sameDefinition = (a: Parts['definition'], b: Parts['definition']) =>
  a.nonterminals === b.nonterminals && a.terminals === b.terminals && a.start.trim() === b.start.trim()

// Two precedence tables are the same when they show the same grid: same terminals in the same order, same relations.
const gridOf = (data: ProjectData) => JSON.stringify(precTable(data.prec))

/** Does the part hold the same value in both contents? */
export function partEquals(part: PartName, a: ProjectData, b: ProjectData): boolean {
  switch (part) {
    case 'definition':
      return sameDefinition(a.def, b.def)
    case 'grammarRules':
      return a.ll.grammar === b.ll.grammar
    case 'precTable':
      return gridOf(a) === gridOf(b)
    case 'reductionRules':
      return a.prec.rules === b.prec.rules
  }
}

/** The parts whose value differs between the two contents, in part order. */
export const changedParts = (a: ProjectData, b: ProjectData): PartName[] => PARTS.filter((part) => !partEquals(part, a, b))
